import re
import time
import logging
from taf.internal.robot_typecasts import time_to_seconds
from taf.sbts.oam.coam.admin import admin
from taf.internal.sbts.admin.exceptions.exception import AdminApiProcedureFailureException
from taf.rfrl.procedures.resources.python.status_check import status_check
from taf.rfrl.procedures.resources.python.status_check.exceptions import IncorrectStatus
from taf.rfrl.bts.devices.du.pm_counters import GnbPmCounter
from taf.rfrl.bts.helpers.compare_statuses import verify_statuses, unify_statuses
from taf.rfrl.bts.devices.exceptions import IncorrectStatuses
from taf.rfrl.utilities.logger.custom_logger import log_info_to_console, log_warn_to_console


class custom_resources:

    LOAD_LEVEL_STATE_MAPPING = {
        'Idle': 'CellsLocked',
        'Low': 'CellsOnAir',
        'Medium': 'TDS',
        'Busy': 'TDS',
        'Full': 'TDS',
    }
    LTE_FAILURE_REGEX = re.compile(r'startLteDownlinkTest.*START_LTE_DOWNLINK_TEST_IND.*'
                                   r'(Start3GPPTestModelFailure|InvalidMessage).*ErrorCode: 69')

    def __init__(self):
        self.admin_cli = admin()

    def check_if_bts_in_required_state_and_change_if_needed(self, connection, load_level, cell_dist_names):
        required_state = self.LOAD_LEVEL_STATE_MAPPING.get(load_level)
        is_in_tds_state = self.is_in_tds_state(connection=connection)
        wait_for_next_pm_period = False
        if required_state == 'CellsLocked':
            if is_in_tds_state:
                log_info_to_console("BTS is in Test Dedicated State, performing Site Reset", log_hierarchy=3)
                self.reset_site_and_wait_for_onair(connection=connection)
                wait_for_next_pm_period = True
            if self.is_cells_locked(connection=connection, cell_dist_names=cell_dist_names):
                log_info_to_console("Cells already locked", log_hierarchy=3)
            else:
                log_info_to_console("Locking cells ...", log_hierarchy=3)
                self.lock_cells_and_wait_until_locked(connection=connection, cell_dist_names=cell_dist_names)
                log_info_to_console("Cells Locked", log_hierarchy=3)
        elif required_state == 'CellsOnAir':
            if is_in_tds_state:
                log_info_to_console("BTS is in Test Dedicated State, performing Site Reset", log_hierarchy=3)
                self.reset_site_and_wait_for_onair(connection=connection)
                wait_for_next_pm_period = True
            if self.is_cells_on_air(connection=connection, cell_dist_names=cell_dist_names):
                log_info_to_console("Cells already in OnAir state", log_hierarchy=3)
            else:
                log_info_to_console("UnLocking cells ...", log_hierarchy=3)
                self.unlock_cells_and_wait_until_onair(connection=connection, cell_dist_names=cell_dist_names)
                log_info_to_console("Cells OnAir", log_hierarchy=3)
        elif required_state == 'TDS':
            if is_in_tds_state:
                log_info_to_console("BTS is already in Test Dedicated State", log_hierarchy=3)
            else:
                log_info_to_console("Resetting to Test Dedicated State ...", log_hierarchy=3)
                self.reset_to_test_dedicated_state_and_wait_until_ready(connection=connection)
                log_info_to_console("BTS in Test Dedicated State", log_hierarchy=3)
                wait_for_next_pm_period = True

        if wait_for_next_pm_period:
            log_info_to_console("Wait for next PM period ...", log_hierarchy=3)
            GnbPmCounter().wait_for_next_pm_period(interval="15min", delay=90)

    def back_to_onair(self, connection, cell_dist_names):
        if self.is_cells_locked(connection=connection, cell_dist_names=cell_dist_names):
            log_info_to_console("Returning to OnAir state by unlocking cells ...", log_hierarchy=2)
            self.unlock_cells_and_wait_until_onair(connection=connection, cell_dist_names=cell_dist_names)
            log_info_to_console("Cells OnAir", log_hierarchy=2)
        elif self.is_in_tds_state(connection=connection):
            log_info_to_console("Returning to OnAir state by Site Reset ...", log_hierarchy=2)
            self.reset_site_and_wait_for_onair(connection=connection)
            log_info_to_console("BTS in OnAir state", log_hierarchy=2)
        elif self.is_cells_on_air(connection=connection, cell_dist_names=cell_dist_names):
            log_info_to_console("BTS already in OnAir state", log_hierarchy=2)
        else:
            log_info_to_console("BTS is in unknown state ...", log_hierarchy=2)

    def is_in_tds_state(self, connection):
        bts_status = self.admin_cli.get_bts_statuses(connection=connection)
        return bts_status['proceduralState'] == 'Test'

    def is_cells_locked(self, connection, cell_dist_names):
        try:
            self.verify_cells_locked(connection=connection, cell_dist_names=cell_dist_names)
            logging.info("Cells are locked")
            return True
        except IncorrectStatuses:
            logging.info("Cells are not locked")
            return False

    def is_cells_on_air(self, connection, cell_dist_names):
        try:
            self.verify_cells_unlocked(connection=connection, cell_dist_names=cell_dist_names)
            logging.info("Cells are on air")
            return True
        except IncorrectStatuses:
            logging.info("Cells are not on air")
            return False

    def lock_cells_and_wait_until_locked(self, connection, cell_dist_names, interval=30, timeout=300):
        self.lock_cells(connection=connection, cell_dist_names=cell_dist_names)
        self._wait_till_succeeds(func=self.verify_cells_locked, exception_to_catch=IncorrectStatuses,
                                 interval=interval, timeout=timeout,
                                 connection=connection, cell_dist_names=cell_dist_names)

    def unlock_cells_and_wait_until_onair(self, connection, cell_dist_names, interval=30, timeout=300):
        self.unlock_cells(connection=connection, cell_dist_names=cell_dist_names)
        self._wait_till_succeeds(func=self.verify_cells_unlocked, exception_to_catch=IncorrectStatuses,
                                 interval=interval, timeout=timeout,
                                 connection=connection, cell_dist_names=cell_dist_names)

    def reset_site_and_wait_for_onair(self, connection, reset_timeout=1200, onair_timeout=600, interval=30):
        self.admin_cli.reset_site(connection=connection, timeout=reset_timeout)
        self._wait_till_succeeds(func=self._check_bts_on_air, exception_to_catch=IncorrectStatus,
                                 interval=interval, timeout=onair_timeout,
                                 connection=connection)

    def reset_to_test_dedicated_state_and_wait_until_ready(self, connection, interval=30, timeout=600):
        self.admin_cli.reset_to_test_dedicated(connection=connection)
        self._wait_till_succeeds(func=self._check_bts_in_tds_state, exception_to_catch=IncorrectStatus,
                                 interval=interval, timeout=timeout, connection=connection)

    def start_downlink_test_model(self, connection, test_model_param, timeout=180):
        if 'NRCELL' in test_model_param['dist_name']:
            bpi = str(test_model_param['beam_pattern_id'])
            sbpi = str(test_model_param['ssb_beam_pattern_id'])
            beam_pattern_id = bpi if isinstance(bpi, list) else bpi.split(',')
            ssb_beam_pattern_id = sbpi if isinstance(sbpi, list) else sbpi.split(',')
            tm_5g_specific_params = {}
            if test_model_param['test_model'] == 'TM1_1_ETSI':
                tm_5g_specific_params = {
                    'load_level_slot_wise': test_model_param['load_level'],
                    'load_type': test_model_param['load_type'],
                    'num_of_ssb_beam_pattern_id': test_model_param['num_of_ssb_beam_pattern_id'],
                    'ssb_beam_pattern_id': ssb_beam_pattern_id,
                }

            self.admin_cli.start_5g_downlink_test(
                connection=connection,
                dist_name=test_model_param['dist_name'],
                test_model=test_model_param['test_model'],
                beam_pattern_id=beam_pattern_id,
                polarization=test_model_param['polarization'],
                power_backoff=test_model_param['power_backoff'],
                ru_mode=test_model_param['ru_mode'],
                phys_cell_id=test_model_param['phys_cell_id'],
                p_max=test_model_param['p_max'],
                nrarfcn_dl=test_model_param['nrarfcn_dl'],
                codebook_2_antports=test_model_param['codebook_2_antports'],
                i11_codebook_4_antports=test_model_param['i11_codebook_4_antports'],
                i2_codebook_4_antports=test_model_param['i2_codebook_4_antports'],
                i13_codebook_4_antports=test_model_param['i13_codebook_4_antports'],
                mimo_rank=test_model_param['mimo_rank'],
                timeout=timeout,
                **tm_5g_specific_params
            )
        else:
            test_model = test_model_param['test_model']
            test_model = 'E_' + test_model if not test_model.startswith('E_') else test_model
            tm_4g_specific_params = {}
            if test_model == 'E_TM1_1_ETSI':
                tm_4g_specific_params = {
                    'load_level': test_model_param['load_level']
                }
            self.admin_cli.start_downlink_test(
                connection=connection,
                dist_name=test_model_param['dist_name'],
                test_model=test_model,
                earfcn=test_model_param['earfcn'],
                p_max=test_model_param['p_max'],
                phy_cell_id=test_model_param['phys_cell_id'],
                tdd_frame_conf=test_model_param.get('tdd_frame_conf'),
                tdd_spec_sub_conf=test_model_param.get('tdd_spec_sub_conf'),
                **tm_4g_specific_params
            )

    def check_if_test_model_is_running(self, connection, cell_id, test_name):
        active_tests = self.admin_cli.get_active_tests(connection=connection, timeout=60)
        logging.debug(f"Active tests: {active_tests}")
        for test in active_tests:
            if test['testInfo'] == test_name and test['cellId'] == cell_id:
                logging.info(f"Test model {test_name} for cell {cell_id} is active.")
                return True
        else:
            raise TestModelNotRunningException(test_name, cell_id)

    def try_to_start_downlink_test_model_and_check_if_running(self, connection, test_model_param, timeout=180,
                                                              allow_fail_for_lte_tm=False):
        try:
            self.start_downlink_test_model(connection=connection, test_model_param=test_model_param, timeout=timeout)
            self.check_if_test_model_is_running(connection=connection,
                                                cell_id=test_model_param['global_cell_id'],
                                                test_name=test_model_param['test_name'])
            return True
        except AdminApiProcedureFailureException as e:
            if allow_fail_for_lte_tm and self.LTE_FAILURE_REGEX.search(repr(e)):

                log_warn_to_console(f"Cannot start {test_model_param['test_model']} on "
                                    f"{test_model_param['cell_name']}. "
                                    f"Most probably is deployed on ABIA which not supports this test model.")
                logging.debug(f"Details: {e}")
            else:
                raise e

    def stop_all_active_downlink_test_models(self, connection, cell_dist_names):
        active_tests = self.admin_cli.get_active_tests(connection=connection, timeout=60)
        logging.debug(f"Active tests: {active_tests}")
        if not active_tests:
            logging.info("No active Test Models found.")
            return

        for cell_dist_name in cell_dist_names:
            stop_method = self.admin_cli.stop_5g_downlink_test \
                if 'NRCELL' in cell_dist_name else self.admin_cli.stop_downlink_test
            try:
                logging.debug(f"Stopping test model for cell: {cell_dist_name}")
                stop_method(connection=connection, dist_name=cell_dist_name, timeout=180)
                logging.info(f"Stopped test model for cell {cell_dist_name}")
            except Exception as e:
                logging.error(f"Failed to stop test model for cell {cell_dist_name}: {e}")

        active_tests = self.admin_cli.get_active_tests(connection=connection, timeout=60)
        if active_tests:
            logging.warning(f"Some test models are still active after stopping: {active_tests}")
        else:
            logging.info("All active downlink test models have been stopped successfully.")

    def lock_cells(self, connection, cell_dist_names):
        for cell_dist_name in cell_dist_names:
            logging.debug(f"Locking cell: {cell_dist_name}")
            self.admin_cli.lock(cell_dist_name, connection=connection, timeout=180)
            logging.info(f"Locked cell {cell_dist_name}")

    def unlock_cells(self, connection, cell_dist_names):
        for cell_dist_name in cell_dist_names:
            logging.debug(f"Unlocking cell: {cell_dist_name}")
            self.admin_cli.unlock(cell_dist_name, connection=connection, timeout=180)
            logging.info(f"Unlocked cell {cell_dist_name}")

    def verify_cells_locked(self, connection, cell_dist_names):
        expected_statuses = {
            "availabilityStatus": "offline",
            "operationalState": "disabled",
            "administrativeState": "locked",
        }

        for cell_dist_name in cell_dist_names:
            cell_specific_info = self.admin_cli.get_cell_specific_info(cell_id=cell_dist_name, connection=connection)
            unify_statuses(cell_specific_info['status'], required_keys=expected_statuses.keys())
            verify_statuses(expected_statuses=expected_statuses, received_statuses=cell_specific_info['status'])
            logging.info("Cell {} is locked".format(cell_dist_name))

    def verify_cells_unlocked(self, connection, cell_dist_names):
        expected_statuses = {
            "availabilityStatus": "online",
            "operationalState": "enabled",
            "administrativeState": "unlocked",
        }

        for cell_dist_name in cell_dist_names:
            cell_specific_info = self.admin_cli.get_cell_specific_info(cell_id=cell_dist_name, connection=connection)
            unify_statuses(cell_specific_info['status'], required_keys=expected_statuses.keys())
            verify_statuses(expected_statuses=expected_statuses, received_statuses=cell_specific_info['status'])
            logging.info("Cell {} is unlocked".format(cell_dist_name))

    @staticmethod
    def _wait_till_succeeds(func, exception_to_catch, interval=30, timeout=300, *args, **kwargs):
        start_time = time.monotonic()
        end_time = start_time + time_to_seconds(time=timeout)
        interval = time_to_seconds(time=interval)
        while time.monotonic() < end_time:
            try:
                func(*args, **kwargs)
                return
            except exception_to_catch as e:
                logging.debug(f"Incorrect Status: {e}")
                logging.info(f"Waiting {interval} seconds for next check")
                time.sleep(interval)
        raise TimeoutError(f"Function {func.__name__} did not succeed within {timeout} seconds")

    def _check_bts_on_air(self, connection):
        logging.debug("Checking if BTS in OnAir state...")
        status_check.verify_statuses_of_bts(connection=connection, status_variant='OnAir')
        logging.info("BTS is in OnAir state")
        logging.debug("Checking if all RUs are online")
        status_check.verify_statuses_of_all_rmods(connection=connection, status_variant='online')
        logging.info("All RUs are online")

        logging.debug("Checking if all Cells are online")

        bts_info = self.admin_cli.get_bts_info(connection=connection, timeout=120)
        rats_states = bts_info.get('ratState', {})
        configured_rats = [rat for rat in rats_states if rats_states.get(rat) != 'NO_CELLS']
        for rat in ['nr', 'lte']:
            if rat in configured_rats:
                status_check.verify_statuses_of_all_cells(connection=connection,
                                                          cells_type=rat, status_variant='online')
        logging.debug("All Cells are online")

    @staticmethod
    def _check_bts_in_tds_state(connection):
        logging.debug("Checking if BTS in Test Dedicated state...")
        status_check.verify_statuses_of_bts(connection=connection, status_variant='Test')
        logging.info("BTS is in Test Dedicated state")
        logging.debug("Checking if all RUs are online")
        status_check.verify_statuses_of_all_rmods(connection=connection, status_variant='online')
        logging.info("All RUs are online")


class TestModelNotRunningException(Exception):
    def __init__(self, test_name, cell_id):
        super().__init__(f"Test {test_name} for CELL {cell_id} is not running")
